package gateway

import (
	"encoding/json/v2"
	"net/http"
	"net/http/httptest"
	"slices"
	"strings"
	"testing"
)

func TestServerRoutes(t *testing.T) {
	srv := NewServer(":8080", nil)
	for _, tc := range []struct {
		method string
		path   string
		status int
	}{
		{"GET", "/healthz", 200},
		{"GET", "/accounts", 200},
		{"GET", "/accounts?active=true", 200},
		{"GET", "/accounts?active=false", 200},
		{"GET", "/accounts?active=", 400},
		{"GET", "/accounts?active=TRUE", 400},
		{"GET", "/accounts?active=1", 400},
		{"GET", "/accounts?active=%zz", 400},
		{"GET", "/accounts?active=true&active=false", 400},
		{"GET", "/accounts/missing", 404},
		{"GET", "/accounts/", 404},
		{"GET", "/accounts/a/b", 404},
		{"GET", "/healthz/", 404},
		{"GET", "/other", 404},
		{"GET", "/accounts/../healthz", 404},
		{"POST", "/unknown", 404},
		{"POST", "/accounts", 405},
		{"HEAD", "/healthz", 405},
		{"HEAD", "/accounts", 405},
		{"DELETE", "/accounts/missing", 405},
	} {
		t.Run(tc.method+" "+tc.path, func(t *testing.T) {
			r := httptest.NewRequest(tc.method, tc.path, nil)
			w := httptest.NewRecorder()
			srv.Handler.ServeHTTP(w, r)
			if w.Code != tc.status {
				t.Errorf("%s %s status = %d, want %d", tc.method, tc.path, w.Code, tc.status)
			}
			if tc.status == 400 && !strings.Contains(w.Body.String(), "active") {
				t.Errorf("GET %s body = %q, want active parameter named", tc.path, w.Body.String())
			}
			if tc.status == 405 && w.Header().Get("Allow") != "GET" {
				t.Errorf("%s %s Allow = %q, want GET", tc.method, tc.path, w.Header().Get("Allow"))
			}
			if tc.path == "/healthz" && tc.method == "GET" && w.Body.String() != "ok" {
				t.Errorf("GET /healthz body = %q, want ok", w.Body.String())
			}
			if tc.status == 200 && strings.HasPrefix(tc.path, "/accounts") && w.Body.String() != "[]" {
				t.Errorf("GET %s body = %q, want []", tc.path, w.Body.String())
			}
		})
	}
}

func TestAccountsSnapshotAndFiltering(t *testing.T) {
	a := Account{ID: "a", Name: "Alice", Cents: 9223372036854775807, Active: true}
	b := Account{ID: "b", Name: "Bob", Cents: -10}
	input := []Account{b, a}
	srv := NewServer(":8080", input)
	if input[0] != b {
		t.Fatalf("NewServer input[0] = %v, want %v", input[0], b)
	}
	input[0] = Account{ID: "mutated"}
	for _, tc := range []struct {
		path string
		want []Account
	}{
		{"/accounts", []Account{a, b}},
		{"/accounts?active=true", []Account{a}},
		{"/accounts?active=false", []Account{b}},
	} {
		t.Run(tc.path, func(t *testing.T) {
			t.Parallel()
			w := httptest.NewRecorder()
			srv.Handler.ServeHTTP(w, httptest.NewRequest(http.MethodGet, tc.path, nil))
			var got []Account
			if err := json.Unmarshal(w.Body.Bytes(), &got); err != nil {
				t.Fatalf("GET %s decode error = %v, want nil", tc.path, err)
			}
			if !slices.Equal(got, tc.want) {
				t.Errorf("GET %s accounts = %v, want %v", tc.path, got, tc.want)
			}
		})
	}
	w := httptest.NewRecorder()
	srv.Handler.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/accounts/b", nil))
	var got Account
	if err := json.Unmarshal(w.Body.Bytes(), &got); err != nil {
		t.Fatalf("GET /accounts/b decode error = %v, want nil", err)
	}
	if got != b {
		t.Errorf("GET /accounts/b account = %v, want %v", got, b)
	}
}

func TestServerLimits(t *testing.T) {
	srv := NewServer(":8080", nil)
	if srv.Addr != ":8080" || srv.Handler == nil {
		t.Errorf("NewServer address/handler = %q/%v, want :8080/non-nil", srv.Addr, srv.Handler)
	}
	if srv.ReadHeaderTimeout <= 0 || srv.ReadTimeout <= 0 || srv.WriteTimeout <= 0 || srv.IdleTimeout <= 0 || srv.MaxHeaderBytes <= 0 || srv.MaxHeaderValueCount <= 0 {
		t.Errorf("NewServer limits = %+v, want positive timeouts and header limits", srv)
	}
}

