package gateway_test

import (
	"encoding/json/v2"
	"net/http"
	"net/http/httptest"
	"slices"
	"strings"
	"testing"

	"probe/gateway"
)

func TestRoutes(t *testing.T) {
	srv := gateway.NewServer(":8080", nil)
	for _, tt := range []struct {
		method, path string
		status       int
	}{
		{http.MethodGet, "/healthz", 200},
		{http.MethodGet, "/accounts", 200},
		{http.MethodGet, "/accounts/missing", 404},
		{http.MethodHead, "/healthz", 405},
		{http.MethodHead, "/accounts", 405},
		{http.MethodPost, "/accounts/missing", 405},
		{http.MethodOptions, "/accounts", 405},
		{http.MethodGet, "/accounts/", 404},
		{http.MethodGet, "/accounts/a/b", 404},
		{http.MethodGet, "//healthz", 404},
		{http.MethodGet, "/healthz/", 404},
		{http.MethodPost, "/unknown", 404},
		{http.MethodGet, "/accounts?active=", 400},
		{http.MethodGet, "/accounts?active=TRUE", 400},
		{http.MethodGet, "/accounts?active=1", 400},
		{http.MethodGet, "/accounts?active=%zz", 400},
		{http.MethodGet, "/accounts?active=true&active=false", 400},
	} {
		t.Run(tt.method+" "+tt.path, func(t *testing.T) {
			t.Parallel()
			w := httptest.NewRecorder()
			srv.Handler.ServeHTTP(w, httptest.NewRequest(tt.method, tt.path, nil))
			if w.Code != tt.status {
				t.Errorf("%s %s status = %d, want %d", tt.method, tt.path, w.Code, tt.status)
			}
			if tt.status == 400 && !strings.Contains(w.Body.String(), "active") {
				t.Errorf("GET %s body = %q, want active parameter named", tt.path, w.Body.String())
			}
		})
	}
	w := httptest.NewRecorder()
	srv.Handler.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/healthz", nil))
	if w.Body.String() != "ok" {
		t.Errorf("GET /healthz body = %q, want ok", w.Body.String())
	}
}

func TestAccountResponses(t *testing.T) {
	a := gateway.Account{ID: "a", Name: "A", Cents: -10, Active: true}
	b := gateway.Account{ID: "b", Name: "B", Cents: 123}
	input := []gateway.Account{b, a}
	srv := gateway.NewServer(":8080", input)
	if !slices.Equal(input, []gateway.Account{b, a}) {
		t.Errorf("NewServer input = %v, want original order", input)
	}
	input[0] = gateway.Account{ID: "changed"}
	for _, tt := range []struct {
		path string
		want []gateway.Account
	}{
		{path: "/accounts", want: []gateway.Account{a, b}},
		{path: "/accounts?active=true", want: []gateway.Account{a}},
		{path: "/accounts?active=false", want: []gateway.Account{b}},
	} {
		t.Run(tt.path, func(t *testing.T) {
			t.Parallel()
			w := httptest.NewRecorder()
			srv.Handler.ServeHTTP(w, httptest.NewRequest(http.MethodGet, tt.path, nil))
			var got []gateway.Account
			if err := json.Unmarshal(w.Body.Bytes(), &got); err != nil {
				t.Fatalf("GET %s decoding failed: %v", tt.path, err)
			}
			if w.Code != 200 || !slices.Equal(got, tt.want) {
				t.Errorf("GET %s = (%d, %v), want (200, %v)", tt.path, w.Code, got, tt.want)
			}
		})
	}
	w := httptest.NewRecorder()
	srv.Handler.ServeHTTP(w, httptest.NewRequest(http.MethodGet, "/accounts/b", nil))
	var got gateway.Account
	if err := json.Unmarshal(w.Body.Bytes(), &got); err != nil {
		t.Fatal(err)
	}
	if w.Code != 200 || got != b || w.Header().Get("Content-Type") != "application/json" {
		t.Errorf("GET /accounts/b = (%d, %v, %q), want (200, %v, application/json)", w.Code, got, w.Header().Get("Content-Type"), b)
	}
}

func TestEmptyArrays(t *testing.T) {
	for _, path := range []string{"/accounts", "/accounts?active=true", "/accounts?active=false"} {
		w := httptest.NewRecorder()
		gateway.NewServer("", nil).Handler.ServeHTTP(w, httptest.NewRequest(http.MethodGet, path, nil))
		if w.Code != 200 || strings.TrimSpace(w.Body.String()) != "[]" {
			t.Errorf("GET %s = (%d, %q), want (200, [])", path, w.Code, w.Body.String())
		}
	}
}

func TestServerLimits(t *testing.T) {
	srv := gateway.NewServer(":8080", nil)
	if srv.Addr != ":8080" || srv.Handler == nil {
		t.Errorf("NewServer(:8080) = %v, want address and handler", srv)
	}
	if srv.ReadHeaderTimeout <= 0 || srv.ReadTimeout <= 0 || srv.WriteTimeout <= 0 || srv.IdleTimeout <= 0 || srv.MaxHeaderBytes <= 0 || srv.MaxHeaderValueCount <= 0 {
		t.Errorf("NewServer limits = %v, want bounded request and connection resources", srv)
	}
}

